import { Fragment } from 'react';
import Link from 'next/link';
import { FEED_LIMITS } from '@app/shared';
import type { A01CData } from './data';

export function A01CMobile(props: A01CData) {
  const { commentaireTexte, commentairesCompte, envoiBloque, filVide, onAnnulerReponse, onCommentaireTexte, onEnvoyerCommentaire, onTriCommentaires, reponseA, thread, triLibelle } = props;

  return (
    <>

      
      <div style={{ position: "fixed", inset: "0", background: "rgba(22,33,29,.55)" }} data-modal-overlay=""></div>
      <div style={{ position: "fixed", left: "0", right: "0", bottom: "0", height: "88%", background: "#fff", borderRadius: "28px 28px 0 0", display: "flex", flexDirection: "column", maxHeight: "calc(100vh - 24px)", overflowY: "auto" }} data-modal-panel="">
        <button type="button" aria-label="Fermer" data-modal-close="" style={{ alignSelf: "center", width: "40px", height: "5px", borderRadius: "999px", background: "#DDE3E0", marginTop: "-10px", flexShrink: "0", border: "none", padding: "20px 24px", font: "inherit", cursor: "pointer", boxSizing: "content-box", marginBottom: "-10px", backgroundClip: "content-box" }}></button>
        <div style={{ padding: "12px 18px", display: "flex", alignItems: "center", borderBottom: "1px solid #EAEEEC", flexShrink: "0" }}><h2 id="a01c-titre" style={{ margin: "0", fontSize: "17px", fontWeight: "800", flex: "1" }}>Commentaires <span style={{ color: "#8A958F" }}>{commentairesCompte}</span></h2><button type="button" onClick={() => { onTriCommentaires(); }} aria-label="Changer le tri des commentaires" data-tri-commentaires="bascule" style={{ display: "flex", alignItems: "center", fontSize: "12.5px", fontWeight: "700", color: "#5D6B66", border: "none", background: "none", padding: 0, font: "inherit", cursor: "pointer" }}>{triLibelle}<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#5D6B66" strokeWidth="2" strokeLinecap="round" style={{ marginLeft: "4px" }}><path d="m6 9 6 6 6-6" /></svg></button></div>
        <div style={{ flex: "1", minHeight: "0", overflowY: "auto", padding: "14px 16px", display: "flex", flexDirection: "column", gap: "14px" }}>
          {(thread ?? []).map((c, cIndex) => (
<Fragment key={cIndex}><div style={{ display: "flex", gap: "10px", paddingLeft: c.indentM }}>{c.retire ? (<div data-commentaire-retire="" style={{ flex: "1", background: "#F2F5F4", borderRadius: "14px", padding: "12px 14px", fontSize: "12.5px", color: "#5D6B66" }}>Ce commentaire a été retiré par la modération.</div>) : (<>
              {c.profil ? (<Link href={c.profil} data-avatar-profil="" aria-label={`Voir le profil de ${c.name}`} style={{ display: "contents", color: "inherit", textDecoration: "none" }}><span style={{ width: "34px", height: "34px", borderRadius: "999px", background: c.bg, color: "#fff", fontSize: "10.5px", fontWeight: "700", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: "0" }}>{c.i}</span></Link>) : (<span style={{ width: "34px", height: "34px", borderRadius: "999px", background: c.bg, color: "#fff", fontSize: "10.5px", fontWeight: "700", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: "0" }}>{c.i}</span>)}
              <div style={{ flex: "1", minWidth: "0" }}><div style={{ background: "#F6F8F7", borderRadius: "14px", padding: "10px 12px" }}><div style={{ display: "flex", alignItems: "center", gap: "5px" }}><span style={{ fontSize: "13px", fontWeight: "700" }}>{c.profil ? (<Link href={c.profil} data-nom-profil="" style={{ color: "inherit", textDecoration: "none" }}>{c.name}</Link>) : c.name}</span><svg width="12" height="12" viewBox="0 0 24 24" fill="#16785E"><circle cx="12" cy="12" r="10" /><path d="m8 12 3 3 5-6" stroke="#fff" strokeWidth="2.2" fill="none" /></svg></div><div style={{ fontSize: "13px", lineHeight: "1.5", marginTop: "2px" }}>{c.text}</div></div><div style={{ display: "flex", gap: "14px", fontSize: "11.5px", color: "#8A958F", marginTop: "5px", paddingLeft: "4px" }}><span>{c.time}</span>{c.likes === undefined ? null : (<span style={{ fontWeight: "700", color: c.likeFg }}>Utile · {c.likes}</span>)}{c.canReply ? (<><button type="button" onClick={c.onRepondre} data-commentaire-repondre="" style={{ fontWeight: "700", color: "#5D6B66", border: "none", background: "none", padding: 0, font: "inherit", cursor: "pointer" }}>Répondre</button></>) : null}<button type="button" onClick={c.onSignaler} disabled={c.onSignaler === undefined} data-commentaire-signaler="" style={{ fontWeight: "600", color: "#8A958F", background: "none", border: "none", padding: 0, font: "inherit", fontSize: "11.5px", cursor: c.onSignaler === undefined ? "default" : "pointer" }}>Signaler</button></div></div>
            </>)}</div></Fragment>
))}{filVide ? (<><div style={{ background: "#fff", border: "1px solid #E6EBE9", borderRadius: "22px", padding: "22px", textAlign: "center" }}><div style={{ fontSize: "15px", fontWeight: "700" }}>Soyez la première personne à réagir.</div><div style={{ fontSize: "12.5px", color: "#5D6B66", marginTop: "4px" }}>Un mot d'encouragement compte.</div></div></>) : null}
        </div>
        {reponseA === null ? null : (<div style={{ flexShrink: "0", padding: "0 12px" }}><div style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "12px", color: "#5D6B66", background: "#F2F5F4", borderRadius: "12px", padding: "8px 12px" }}>En réponse à <strong style={{ color: "#16211D" }}>{reponseA}</strong><span style={{ flex: "1" }}></span><button type="button" onClick={onAnnulerReponse} aria-label="Annuler la réponse" data-reponse-annuler="" style={{ minWidth: "44px", minHeight: "44px", border: "none", background: "none", padding: 0, font: "inherit", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M18 6 6 18M6 6l12 12" /></svg></button></div></div>)}<div style={{ flexShrink: "0", borderTop: "1px solid #EAEEEC", padding: "10px 12px 26px", display: "flex", gap: "8px", alignItems: "center" }}><div style={{ flex: "1", height: "44px", borderRadius: "999px", background: "#F2F5F4", padding: "0 16px", display: "flex", alignItems: "center", fontSize: "13.5px", color: "#8A958F" }}><input type="text" value={commentaireTexte} onChange={onCommentaireTexte} placeholder="Écrire un commentaire…" aria-label="Écrire un commentaire…" data-commentaire-texte="" maxLength={FEED_LIMITS.commentBodyMax} style={{ flex: "1", minWidth: "0", border: "none", background: "transparent", font: "inherit", color: "#16211D", outline: "none", padding: 0 }} /></div><button type="button" onClick={onEnvoyerCommentaire} disabled={envoiBloque} aria-label="Envoyer" data-commentaire-envoyer="" style={{ width: "44px", height: "44px", borderRadius: "999px", background: "#16785E", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "inherit", color: "inherit", cursor: "pointer", border: "none", opacity: envoiBloque ? ".55" : "1" }}><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14m-6-6 6 6-6 6" /></svg></button></div>
      </div>
    
    </>
  );
}
